package org.springframework.samples.petclinic.util;

import org.springframework.samples.petclinic.model.Owner;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

/**
 * Derives an owner's numeric membership level. The level starts at {@link #BASE} and gains a
 * point for each qualifying factor: a present email, having no namesakes ({@code namesakeCount}
 * is 0), and tenure of more than {@link #TENURE_DAYS} days since registration. It is capped at
 * {@link #MAX}. A newly created owner has zero tenure, so the tenure point is out of reach on
 * creation and a new owner never exceeds level 3.
 */
public final class MembershipLevels {

    /** Level every owner starts at. */
    public static final int BASE = 1;

    /** Highest level derivable here; reachable only with the tenure point. */
    public static final int MAX = 4;

    /** Tenure, in days since registration, must exceed this for the tenure point. */
    public static final int TENURE_DAYS = 365;

    private MembershipLevels() {
    }

    /** Return the membership level (1 to 4) for {@code owner} as at {@code asOf}. */
    public static int of(Owner owner, LocalDate asOf) {
        int level = BASE;
        if (owner.hasEmail()) {
            level++;
        }
        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
            level++;
        }
        if (hasTenure(owner, asOf)) {
            level++;
        }
        return Math.min(level, MAX);
    }

    /** Whether the owner's tenure as at {@code asOf} exceeds {@link #TENURE_DAYS} days. */
    private static boolean hasTenure(Owner owner, LocalDate asOf) {
        LocalDate registration = owner.getRegistrationDate();
        if (registration == null || asOf == null) {
            return false;
        }
        return ChronoUnit.DAYS.between(registration, asOf) > TENURE_DAYS;
    }
}

package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
import org.springframework.samples.petclinic.util.AgeBand;
import org.springframework.samples.petclinic.util.CustomerCode;
import org.springframework.samples.petclinic.util.Luhn;
import org.springframework.samples.petclinic.util.MembershipLevels;
import org.springframework.samples.petclinic.util.Telephones;

import java.time.LocalDate;
import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "displayName", expression = "java(displayName(owner))")
    @Mapping(target = "initials", expression = "java(initials(owner))")
    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
    @Mapping(target = "locality", expression = "java(locality(owner))")
    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
    @Mapping(target = "sharesHousehold", ignore = true)
    OwnerDto toOwnerDto(Owner owner);

    /** Format an owner's name as 'LastName, FirstName' for display. */
    default String displayName(Owner owner) {
        return owner.getLastName() + ", " + owner.getFirstName();
    }

    /** Upper-cased first letters of first and last name, dot-separated with a trailing dot (e.g. 'J.S.'). */
    default String initials(Owner owner) {
        return initial(owner.getFirstName()) + initial(owner.getLastName());
    }

    private static String initial(String name) {
        return Character.toUpperCase(name.charAt(0)) + ".";
    }

    /**
     * Derive the membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last
     * two digits of the registration date year (e.g. 'SYD-SMI-0007-M26'). Returns null when
     * either source field is absent.
     */
    default String membershipNumber(Owner owner) {
        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
            return null;
        }
        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
    }

    /**
     * Derive the Luhn check digit (0 to 9) over the digits of the owner's customer code.
     * Returns null when the customer code has not yet been assigned.
     */
    default Integer checkDigit(Owner owner) {
        if (owner.getCustomerCode() == null) {
            return null;
        }
        return Luhn.checkDigit(owner.getCustomerCode());
    }

    /**
     * Derive the owner's locality (canonical region) as the region component of the customer
     * code identity, or 'UNKNOWN' when the code carries no region.
     */
    default String locality(Owner owner) {
        return CustomerCode.regionOf(owner.getCustomerCode());
    }

    /** Derive the owner's numeric membership level (1 to 4) as at the current date. */
    default Integer membershipLevel(Owner owner) {
        return MembershipLevels.of(owner, LocalDate.now());
    }

    /** Derive the owner's preferred contact method: EMAIL when an email is present, otherwise PHONE. */
    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
        return owner.hasEmail() ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
    }

    /**
     * Derive the owner's age band from the birth date as at the registration date, or null
     * when no birth date was supplied.
     */
